        console.log("--- OPERATION: Owner initialization ---");
        vm.prank(owner);
        wallet.initWallet();

        console.log("--- AFTER-Trigger (Owner Set) ---");
        console.log("Creator address: %s (should be owner)", getCreator());
        assertEq(getCreator(), owner, "Owner should be set initially");

